-- Owned additions, replay safety, price snapshots, sale expiry and account isolation.
select no_plan();
select tests.create_shoppers_fixture();
select ok(not has_function_privilege('anon','public.add_shopper_list(uuid,uuid,uuid,uuid,int)','EXECUTE'),'public visitors cannot add lists');
select ok(not has_function_privilege('anon','public.set_list_quantity(uuid,uuid,int)','EXECUTE'),'public visitors cannot change quantities');
select ok(not has_function_privilege('anon','public.shopper_account()','EXECUTE'),'public visitors cannot read accounts');
select ok(not has_function_privilege('authenticated','private.list_sale_end(uuid)','EXECUTE'),'sale calculation remains private');
select ok(not has_table_privilege('authenticated','private.shopper_list_requests','SELECT'),'replay keys are private');
update public.plan_candidates set soundtrack_track_id='a3000000-0000-0000-0000-000000000001',soundtrack_analysis_id='a4000000-0000-0000-0000-000000000001' where id='a1000000-0000-0000-0000-000000000002';
select tests.act_as('anonymous_shopper');
select lives_ok($$select public.add_shopper_list('90000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001')$$,'anonymous shopper saves a product');
select is((select count(*) from public.lists where shopper_id=auth.uid()),3::bigint,'addition creates one list');
select is((select count(*) from public.lists where till_code ~ '^[0-9]{16}$'),3::bigint,'every owned code has sixteen digits');
select is((select valid_until from public.lists where plan_candidate_id is null and status='open'),make_date(extract(year from now() at time zone 'Europe/London')::int,12,31),'all-year list uses calendar year end');
select lives_ok($$select public.add_shopper_list('90000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001')$$,'replaying the add is safe');
select is((select sum(item.quantity) from public.list_items item join public.lists list on list.id=item.list_id where list.plan_candidate_id is null and list.status='open'),1::bigint,'retry does not double quantity');
reset role;
update public.range_items set price_minor=3900 where id='91000000-0000-0000-0000-000000000002';
select tests.act_as('anonymous_shopper');
select lives_ok($$select public.add_shopper_list('90000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000002','60000000-0000-0000-0000-000000000001')$$,'second addition reuses product list');
select is((select count(*) from public.lists where shopper_id=auth.uid()),3::bigint,'second addition reuses the list');
select is((select sum(item.quantity) from public.list_items item join public.lists list on list.id=item.list_id where list.plan_candidate_id is null and list.status='open'),2::bigint,'second addition increases quantity');
select is((select item.unit_price_minor from public.list_items item join public.lists list on list.id=item.list_id where list.plan_candidate_id is null and list.status='open'),2500::bigint,'price stays at first-add snapshot');
select lives_ok($$select public.set_list_quantity((select id from public.lists where plan_candidate_id is null and status='open'),'60000000-0000-0000-0000-000000000001',3)$$,'owned quantity changes');
select is((select item.unit_price_minor from public.list_items item join public.lists list on list.id=item.list_id where list.plan_candidate_id is null and list.status='open'),2500::bigint,'quantity changes preserve saved price');
select throws_ok($$select public.set_list_quantity((select id from public.lists where plan_candidate_id is null and status='open'),'60000000-0000-0000-0000-000000000001',1000)$$,'23514','Quantity exceeds current stock','cannot exceed current stock');
select throws_ok($$select public.set_list_quantity('a2000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001',2)$$,'42501','Own list required','another shopper list denied');
select throws_ok($$select public.set_list_quantity('a2000000-0000-0000-0000-000000000004','60000000-0000-0000-0000-000000000001',2)$$,'23514','List is no longer editable','redeemed list cannot change');
select throws_ok($$select public.add_shopper_list('90000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000003',null,'a1000000-0000-0000-0000-000000000001',0)$$,'42501','Own candidate at matching store required','foreign plan cannot be saved');
select throws_ok($$select public.add_shopper_list('90000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000003',null,'a1000000-0000-0000-0000-000000000002',1)$$,'23514','Plan changed; reload before saving','stale plan revision rejected');
select lives_ok($$select public.add_shopper_list('90000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000003',null,'a1000000-0000-0000-0000-000000000002',0)$$,'owned plan saves its list and show');
select is((select count(*) from public.shows where owner_id=auth.uid()),1::bigint,'plan save creates one owned show');
select is((select cues from public.show_versions where owner_id=auth.uid()),tests.show_cues(),'saved cues retain candidate snapshot');
select is((select soundtrack_analysis_id from public.show_versions where owner_id=auth.uid()),'a4000000-0000-0000-0000-000000000001'::uuid,'saved show pins exact candidate music analysis');
select is((select status from public.plan_sessions where id='a0000000-0000-0000-0000-000000000002'),'listed','plan marked listed');
select lives_ok($$select public.add_shopper_list('90000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000003',null,'a1000000-0000-0000-0000-000000000002',0)$$,'plan save replay is safe');
select is((select count(*) from public.shows where owner_id=auth.uid()),1::bigint,'plan replay does not duplicate saved show');
select is(jsonb_array_length(public.shopper_account()->'plans'),1,'account history includes only own session');
select is(jsonb_array_length(public.shopper_account()->'lists'),4,'account includes only own lists');
select ok(not public.shopper_account()::text like '%1111111111111111%','account hides foreign till codes');
select lives_ok($$select public.set_list_quantity((select id from public.lists where plan_candidate_id is null and status='open'),'60000000-0000-0000-0000-000000000001',0)$$,'zero removes an owned item');
select is((select count(*) from public.list_items item join public.lists list on list.id=item.list_id where list.plan_candidate_id is null and list.status='open'),0::bigint,'removal leaves the list empty');
reset role;
select tests.act_as('signed_in_shopper');
select throws_ok($$select public.add_shopper_list('90000000-0000-0000-0000-000000000002','b0000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000001')$$,'42501','List request ownership mismatch','cannot replay another shopper request');
select is(jsonb_array_length(public.shopper_account()->'plans'),1,'permanent account also sees only own history');
reset role;
select is((select sum(qty_after) from public.stock_movements where store_id='90000000-0000-0000-0000-000000000002'),10::bigint,'lists never reserve stock');
update public.stores set licence='seasonal' where id='90000000-0000-0000-0000-000000000002';
delete from public.sale_periods where market='GB';
insert into public.sale_periods(market,name,rule) values ('GB','Current fixture window',jsonb_build_object('type','fixed','from',to_char(now() at time zone 'Europe/London' - interval '1 day','MM-DD'),'to',to_char(now() at time zone 'Europe/London' + interval '1 day','MM-DD')));
select is(private.list_sale_end('90000000-0000-0000-0000-000000000002'),(now() at time zone 'Europe/London')::date + 1,'fixed window derives closing day');
delete from public.sale_periods where market='GB';
select throws_ok($$select private.list_sale_end('90000000-0000-0000-0000-000000000002')$$,'23514','Shop sales are closed','unsupported or absent sale period fails closed');
update public.stores set licence='all_year' where id='90000000-0000-0000-0000-000000000002';
update public.lists set valid_until=(now() at time zone 'Europe/London')::date - 1 where id='a2000000-0000-0000-0000-000000000002';
select tests.act_as('anonymous_shopper');
select throws_ok($$select public.set_list_quantity('a2000000-0000-0000-0000-000000000002','60000000-0000-0000-0000-000000000001',2)$$,'23514','List is no longer editable','expired list cannot change before maintenance runs');
select is((select value->>'status' from jsonb_array_elements(public.shopper_account()->'lists') where value->>'id'='a2000000-0000-0000-0000-000000000002'),'expired','reader hides expired barcode before maintenance runs');
reset role;
update public.stores set timezone='Etc/GMT+12' where id='90000000-0000-0000-0000-000000000002';
set local timezone='Pacific/Kiritimati';
select tests.act_as('anonymous_shopper');
select lives_ok($$select public.create_list('90000000-0000-0000-0000-000000000002','[{"product_id":"60000000-0000-0000-0000-000000000001","quantity":1}]','5555555555555555',(now() at time zone 'Etc/GMT+12')::date)$$,'list creation accepts the inclusive store day despite a later caller calendar');
reset role;
set local timezone='UTC';
update public.profiles set status='suspended' where id=tests.get_supabase_uid('anonymous_shopper');
select tests.act_as('anonymous_shopper');
select throws_ok($$select public.shopper_account()$$,'42501','Active shopper required','suspended account fails closed');
reset role;
select finish();
